void execute_vault_0_schedule()
{
  printf("=== Executing NMP Schedule for Vault %d (%d instructions) ===\n", TARGET_VAULT_ID, TOTAL_INSTRUCTIONS);
  for (int i = 0; i < TOTAL_INSTRUCTIONS; i++)
  {
    const NMPInstruction *inst = &VAULT_0_SCHEDULE[i];
    printf("[%03d] [%s] %-12s | Addr: 0x%08X | Size: %6u bytes | ClearAcc: %d\n", i, inst->stage, inst->op, inst->addr, inst->size, inst->clear_acc);
  }
}